  const cookie = login.response.headers.getSetCookie().find(value => value.startsWith('janeq_access_token='));
  if (!cookie) throw new Error('HttpOnly cookie missing');
  const cookieFlags = { httpOnly: /; HttpOnly/i.test(cookie), secure: /; Secure/i.test(cookie), sameSiteLax: /; SameSite=Lax/i.test(cookie), pathRoot: /; Path=\//i.test(cookie) };
  if (!cookieFlags.httpOnly || !cookieFlags.sameSiteLax || !cookieFlags.pathRoot) throw new Error('cookie flags incorrect');
  if ('accessToken' in login.body || 'refreshToken' in login.body) throw new Error('token leaked in response body');
  const cookiePair = cookie.split(';', 1)[0];
  const me = await call('/auth/me', { headers: { cookie: cookiePair } });
  if (!me.response.ok || me.body.username !== 'emilys' || 'accessToken' in me.body) throw new Error('cookie auth/me failed');
  const logout = await call('/auth/logout', { method: 'POST', headers: { cookie: cookiePair, origin: 'http://localhost:5173' } });
